ed(C + '07-SIGNIFICANCE.md', 'Under the laws of `Flow.persists_never_overdraws`', 'Under the premises of `Flow.persists_never_overdraws`')
ed(C + '07-SIGNIFICANCE.md', 'a World meeting the persistence laws', 'a World meeting the persistence premises')
ed(C + '07-SIGNIFICANCE.md', 'The World is a model of those laws', 'The World is a model of those premises')
ed(C + '08-METHOD.md', 'with no law of possibility', 'with no theorem on possibility')
# ---- headings that name theorems; the old anchors stay beside the new
ed(B + 'USES.md', '## Exits and design laws\n', '<a id="exits-and-design-laws"></a>\n## Exits and design theorems\n')
ed(B + 'USES.md', '[after the fields](#exits-and-design-laws), exits and design laws, each on its model', '[after the fields](#exits-and-design-laws), exits and design theorems, each on its model')
ed(B + 'USES.md', 'exits and design laws on their models', 'exits and design theorems on their models')
ed(B + 'COLLECTIVE-DIRECTION.md', "\n## 3. What the theory's own laws rule out\n", "\n<a id=\"3-what-the-theorys-own-laws-rule-out\"></a>\n## 3. What the theory's own theorems rule out\n")
ed(C + '01-ROOT.md', '## 9. Laws on every model, each with its hypotheses\n', '<a id="9-laws-on-every-model-each-with-its-hypotheses"></a>\n## 9. Theorems on every model, each with its hypotheses\n')
ed(C + '05-COLLECTIVES.md', '## 7. The optimum: one law, its cases\n', '<a id="7-the-optimum-one-law-its-cases"></a>\n## 7. The optimum: one theorem, its cases\n')
# ---- the opening (Ren's first person, revised in place since 31 October 2026)
O = B + 'OPENING.md'
ed(O, '"The law shows", "This law, with that one step"', '"The theorems show", "These theorems, with that one step"')
ed(O, 'where the conditions a law names hold, its dynamics follow, and where one fails, the law no longer guarantees the conclusions that used it', 'where the conditions a theorem names hold, its dynamics follow, and where one fails, the theorem no longer guarantees the conclusions that used it')
ed(O, 'each law is proved from how the theory represents a world', 'each theorem is proved from how the theory represents a world')
