ed(O, "what the law marks is what a course closes", "what the theorems mark is what a course closes")
ed(O, 'The law shows what each does, and the one step counts all of it', 'The theorems show what each does, and the one step counts all of it')
ed(O, "The work's selection laws restate the proxy problem", "The work's selection theorems restate the proxy problem")
ed(O, 'can check that each law follows from its stated premises', 'can check that each theorem follows from its stated premises')
ed(O, 'None of them follows from the laws: each fails in a world the laws admit, and the laws show what each leaves out', 'None of them follows from the theorems: each fails in a world the theorems admit, and the theorems show what each leaves out')
ed(O, 'and the laws say exactly what holds it there', 'and the theorems say exactly what holds it there')
# the opening's notes
ed(O, 'three laws follow: over any stretch', 'three theorems follow: over any stretch')
ed(O, 'The laws hold by what change and count are, so nothing can break them, and they are not a dynamics, which the laws under conditions state.', 'The theorems hold by what change and count are, so nothing can break them, and they are not a dynamics, which the theorems under conditions state.')
ed(O, 'and several laws rely on whole-number amounts', 'and several theorems rely on whole-number amounts')
