ed(O, 'The laws hold, as theorems, of every Petri net', 'The theorems hold of every Petri net')
ed(O, "now one law with the spine's: agreement with known results, not independent evidence that the laws are general.", "now one with the spine's theorems: agreement with known results, not independent evidence that the theorems are general.")
ed(O, '(a reading: no law picks the relation or the centers', '(a reading: no theorem picks the relation or the centers')
ed(O, 'the laws show it mixed and weigh it for no one (the note on good and evil)', 'the theorems show it mixed and weigh it for no one (the note on good and evil)')
ed(O, 'and the laws do not exclude a fixed restraint', 'and the theorems do not exclude a fixed restraint')
ed(O, 'since the laws ask no self-enlargement', 'since the theorems ask no self-enlargement')
ed(O, 'so retaining orders neither; the laws show it mixed and weigh it for no one', 'so retaining orders neither; the theorems show it mixed and weigh it for no one')
