ed(O, '**What the laws contain is read off them; the diagnosis is a judgment.** The laws with no premise exclude no unfolding', '**What the theorems contain is read off them; the diagnosis is a judgment.** The theorems with no premise exclude no unfolding')
ed(O, 'each premise of the conditional laws holds in one constructed world', 'each premise of the conditional theorems holds in one constructed world')
ed(O, 'That none of the three follows from the laws is proved of a reading of each', 'That none of the three follows from the theorems is proved of a reading of each')
ed(O, 'a constructed example with the joint-excess law', 'a constructed example with the joint-excess theorem')
ed(O, "the model's law standing only within its hypotheses", "the model's theorem standing only within its hypotheses")
ed(O, '"The laws say exactly what holds it there" is said of that model', '"The theorems say exactly what holds it there" is said of that model')
