ed(O, 'reads the dependence laws above; it is no separate theorem', 'reads the dependence theorems above; it is no theorem of its own')
bad = 0
for path, lst in E.items():
    p = f'{tree}/{path}'; s = open(p, encoding='utf-8').read()
    for old, new, n in lst:
        k = s.count(old)
        if k != n: print('MISMATCH', path, k, 'expected', n, '|', old[:80]); bad += 1; continue
        s = s.replace(old, new)
    with open(p, 'w', encoding='utf-8') as f: f.write(s)
print('files', len(E), 'edits', sum(len(v) for v in E.values()), 'mismatches', bad)
sys.exit(1 if bad else 0)
